  ".aurora-store-filters::-webkit-scrollbar{display:none;}" +
  ".aurora-store-idcard{align-items:flex-start;padding:0.7em 0.8em;}" +
  ".aurora-store-share{padding:0.9em 1em 1em;}" +
  ".aurora-store-grid{gap:12px;}" +
  // The drawer is 92vw here, so its 1.3em gutters cost real reading width.
  ".aurora-store-panes{padding:0.8em 1em 0;gap:8px;}" +
  ".aurora-store-drawer-body{padding:0.9em 1em;}" +
  ".aurora-store-drawer-foot{padding:0.8em 1em;}" +
  // Still two columns -- the labels are short and stacking would double the
  // table's height -- but the 18px gutter is room the values need here.
  ".aurora-store-kv{gap:5px 10px;}" +
  // 44% of a 300px drawer ellipsised most targets down to nothing, so a
  // shortcut becomes two lines here: glyph + title + the ↗ marker, then the
  // target underneath, indented to line up with the title. `order` is what
  // keeps ↗ next to the title it marks -- it sits after the target in the
  // DOM, and without it the marker gets pushed onto a third line of its own.
  ".aurora-store-sc li{flex-wrap:wrap;gap:4px 10px;}" +
  ".aurora-store-sc .nm{flex:1 1 auto;}" +
  ".aurora-store-sc .to{order:1;flex:1 1 100%;max-width:100%;" +
  "padding-left:34px;}" +
  "}";

return view.extend({
  handleSave: null,
  handleSaveApply: null,
  handleReset: null,

  load() {
    // 刻意只留本地来源。presets.json 随包安装,uci.load 走本机 ubus(实测
    // ~90ms)。到 hub 的两个调用移到 render() 之后 —— LuCI 在 load() resolve
    // 前不会进 render(),把一次 205ms RTT / 首连 800ms 的往返放在这里,等于
    // 让首屏白等它。
    return Promise.all([
      L.resolveDefault(
        fetch(L.resource("aurora/presets.json") + "?v=" + PRESETS_VERSION).then(
          (res) => (res.ok ? res.json() : null),
        ),
        null,
      ),
      // 纯本地的一次 ubus(约 0.09s,见 docs/specs/2026-08-05-store-first-paint.md)。
      // 它回答的是整页最要紧的那件事:钩子该落在哪张卡上。
      L.resolveDefault(hubApi.callHubLocalState(), null),
      uci.load("aurora"),
    ]).then(([presetsRes, localState]) => ({
      presets: (presetsRes && presetsRes.presets) || null,
      // 单一真相。active_preset 与 hub_applied 都还在 uci 里给各自的老消费者
      // 用(studio 的表单、get_init_data),但商店的匹配只认这一个。
      activeSource: (localState && localState.active_source) || "",
      // 当前外观还等于上次从商店里选的那张卡吗。为假 = 这套外观是用户自己的。
      modified: Boolean(localState && localState.modified),
      // 被商店主题盖掉之前的样子,投影成 presets.json 行的形状。
      backupPreview: (localState && localState.backup) || null,
      // Set by rpcd whenever the key leaves the router (export or import).
      // Lives in uci rather than localStorage so it follows a keep-settings
      // upgrade, survives a browser change, and resets to zero on the clean
      // reflash that is exactly when the reminder should come back.
      keySaved: uci.get("aurora", "theme", "hub_key_saved") === "1",
      // This router's own navigation shape. It used to stand in for the
      // built-in presets' too, back when a preset changed only colours; now
      // every preview draws the configuration's own nav_type and this is read
      // by the publish panel alone -- the preview and manifest of what YOUR
      // configuration would look like in the store.
      navType: uci.get("aurora", "theme", "nav_type") || "mega-menu",
      // 会随这份配置一起上传的自定义字体([{slot,family,size}])。rpcd 用的是
      // build_share_payload 打包时的同一个判断,所以发布面板上写着要发什么,
      // 线路上发的就是什么。名册预设不在其中 —— 接收端自己去下载。
      sharedFonts: (localState && localState.shared_fonts) || [],
      // 同理,会随这份配置发出去的图片和快捷方式图标,带体积。发布面板过去
      // 对图片只写一句 "Included" —— 而体积才是收到这份主题的人真正要拿来
      // 做决定的东西,尤其是 flash 只剩一两 MB 的设备。
      sharedImages: (localState && localState.shared_images) || [],
      sharedToolbarIcons: (localState && localState.shared_toolbar_icons) || [],
    }));
  },

  render(loadData) {
    // 钩子落在「等于当前外观」的那张卡上。一张都不等于 —— 也就是 modified ——
    // 就说明当前外观是用户自己的,「我的配置」那张卡代表它。整页的选中态只由
    // 这两个值决定,没有第三处真相。
    const activeSource = loadData.activeSource;
    const modified = loadData.modified;
    const backupPreview = loadData.backupPreview;
    const currentNav = loadData.navType;
    const sharedFonts = loadData.sharedFonts;
    const sharedImages = loadData.sharedImages;
    const sharedToolbarIcons = loadData.sharedToolbarIcons;

    const isCurrentBuiltin = (preset) =>
      !modified && activeSource === "builtin:" + preset.id;
    const isCurrentOnline = (item) =>
      !modified && activeSource === "hub:" + item.id;

    // Built-in preset card models: local data, offline-safe. When presets.json
    // is missing (broken install) the group renders nothing.
    //
    // `preview` is the projection a hub list row carries (colors / layout /
    // typography / toolbar), written by scripts/gen-presets.mjs from the same
    // templates rpcd applies. That is the whole point of the shape: paletteOf,
    // navOf and tileEntriesFor then read a built-in preset with the accessors
    // they already use for a shared configuration, so the two card kinds
    // cannot describe a look differently.
    const builtinItems = loadData.presets
      ? BUILTIN_PRESETS.filter((preset) => loadData.presets[preset.id]).map(
          (preset) => ({
            id: preset.id,
            label: preset.label,
            preview: loadData.presets[preset.id],
          }),
        )
      : [];

    const state = {
      tab: "all",
      query: "",
      online: { hot: null, new: null },
      onlineFailed: false,
      showingStale: false,
    };

    const styleEl = E("style", { type: "text/css" });
    styleEl.textContent = STORE_CSS;

    const rootEl = E("div", { class: "cbi-map aurora-store" });
    const contentEl = E("div", {});
    const drawerMask = E("div", { class: "aurora-store-mask" });
    const drawerEl = E("div", { class: "aurora-store-drawer" });

    const closeDrawer = () => rootEl.classList.remove("aurora-store-open");
    drawerMask.addEventListener("click", closeDrawer);

    // ------------------------------------------------------------------
    // Rolling back to your own configuration

    // 「我的配置」那张卡的 apply。措辞和应用任何一张卡一致 —— 对用户来说这
    // 就是同一件事,只是这一张碰巧是他自己的。
    const confirmRestore = () => {
      ui.showModal(_("Apply My Configuration"), [
        E(
          "p",
          {},
          _(
            "This puts back the look you had before applying a theme from the store.",
          ),
        ),
        buildConfirmActions(() => {
          ui.showModal(_("Applying"), [
            E("p", { class: "spinning" }, _("Applying…")),
          ]);
          L.resolveDefault(hubApi.callHubRestore(), null).then((res) => {
            if (res && res.result === 0) {
              window.location.reload();
              return;
            }
            ui.hideModal();
            ui.addNotification(
              null,
              E("p", {}, restoreErrorMessage(res && res.error)),
              "warning",
            );
          });
        }, _("Apply")),
      ]);
    };

    // ------------------------------------------------------------------
    // Online apply flow (backup -> job -> poll -> reload)

    const pollApplyStatus = (jobId, remaining) => {
      if (remaining <= 0) {
        ui.hideModal();
        ui.addNotification(
          null,
          E("p", {}, _("Applying timed out. Please try again.")),
          "warning",
        );
        return;
      }

      window.setTimeout(() => {
        L.resolveDefault(hubApi.callGetHubStatus(jobId), {}).then((status) => {
          if (status && status.state === "done") {
            ui.hideModal();
            ui.addNotification(null, E("p", {}, _("Applied.")), "info");
            // 应用完必须重新加载,否则画面和应用前一模一样 —— 颜色、字体、
            // 图片全是 header.ut 在服务端渲染进文档的(字体 CSS 用 readfile
            // 内联,图片靠 icon_cache_version 打戳),都只在文档加载时求值一
            // 次。内置预设和回滚两条路径一直都这么收尾。
            //
            // 重新加载也是钩子挪位的唯一途径:active_source 与指纹是 rpcd 在
            // 收尾时写的,只有再读一次 load() 才知道该落在哪张卡上。
            window.location.reload();
          } else if (status && status.state === "error") {
            ui.hideModal();
            ui.addNotification(
              null,
              E("p", {}, applyErrorMessage(status.error)),
              "warning",
            );
          } else {
            pollApplyStatus(jobId, remaining - 1);
          }
        });
      }, 1500);
    };

    const startApply = (id) => {
      ui.showModal(_("Applying"), [
        E("p", { class: "spinning" }, _("Applying this configuration…")),
      ]);
      L.resolveDefault(hubApi.callHubApply(id), null).then((res) => {
        if (!res || res.result !== 0 || !res.job_id) {
          ui.hideModal();
          ui.addNotification(
            null,
            E("p", {}, applyErrorMessage(res && res.error)),
            "warning",
          );
          return;
        }
        pollApplyStatus(res.job_id, 20);
      });
    };

    const confirmOnlineApply = (item) => {
      closeDrawer();
      const urls = externalToolbarUrls(item.payload || {});
      const onConfirm = () => startApply(item.id);
      ui.showModal(
        _("Apply Configuration"),
        urls.length
          ? buildExternalUrlConfirm(urls, onConfirm)
          : buildSimpleApplyConfirm(onConfirm),
      );
    };

    // Quick apply from a card: the external-URL callout needs the full
    // payload, so fetch the detail first, then reuse the drawer's confirm.
    const quickApplyOnline = (id) => {
      ui.showModal(_("Applying"), [
        E("p", { class: "spinning" }, _("Loading theme details…")),
      ]);
      L.resolveDefault(hubApi.callHubGet(id), null).then((res) => {
        ui.hideModal();
        if (!res || res.result !== 0 || !res.data) {
          ui.addNotification(
            null,
            E("p", {}, applyErrorMessage(res && res.error)),
            "warning",
          );
          return;
        }
        confirmOnlineApply(res.data);
      });
    };

    // ------------------------------------------------------------------
    // Built-in preset apply: local rpcd path, identical semantics (and
    // msgids) to the old preset dropdown -- colors only, immediate, reload.

    const confirmBuiltinApply = (preset) => {
      closeDrawer();
      ui.showModal(_("Apply Preset"), [
        E(
          "p",
          {},
          _(
            "Apply the '%s' preset now? It is saved immediately and the page reloads. A preset carries a whole look — colors, navigation, spacing, corner radius, content width, fonts and shortcuts. Whatever the theme you are wearing now brought with it is replaced; images you uploaded yourself stay as they are.",
          ).format(preset.label),
        ),
        buildConfirmActions(() => {
          ui.showModal(_("Applying..."), [
            E("p", { class: "spinning" }, _("Applying preset...")),
          ]);
          L.resolveDefault(callApplyThemePreset(preset.id), {}).then((ret) => {
            ui.hideModal();
            if (ret && ret.result === 0) {
              ui.addNotification(
                null,
                E("p", _("Preset applied successfully.")),
                "info",
              );
              window.location.reload();
            } else {
              ui.addNotification(
                null,
                E(
                  "p",
                  _("Apply failed: %s").format(
                    (ret && ret.error) || _("Unknown"),
                  ),
                ),
                "error",
              );
            }
          });
        }, _("Apply")),
      ]);
    };

    // ------------------------------------------------------------------
    // Detail drawer

    const renderDrawer = (children) => {
      while (drawerEl.firstChild) drawerEl.removeChild(drawerEl.firstChild);
      children.forEach((child) => drawerEl.appendChild(child));
      rootEl.classList.add("aurora-store-open");
    };

    const drawerFoot = (applyLabel, onApply, current) =>
      E("div", { class: "aurora-store-drawer-foot" }, [
        E("button", { type: "button", class: "btn", click: closeDrawer }, _("Close")),
        current
          ? E(
              "button",
              { type: "button", class: "btn apply", disabled: "disabled" },
              "✓ " + _("In use"),
            )
          : E(
              "button",
              {
                type: "button",
                class: "btn cbi-button-action important apply",
                click: onApply,
              },
              applyLabel,
            ),
      ]);

    const openBuiltinDrawer = (preset) => {
      const current = isCurrentBuiltin(preset);
      const typography = preset.preview.typography || {};
      const title = E("h3", { style: "margin:0 0 0.3em;" }, [
        document.createTextNode(preset.label),
        " ",
        E("span", { class: "aurora-store-badge builtin" }, _("Built-in")),
      ]);
      if (current) title.appendChild(buildCurrentTick());

      const body = [
        title,
        E(
          "p",
          { class: "aurora-store-dt-desc" },
          _("Ships with the theme and works offline."),
        ),
        buildDetailHeading(_("Colors")),
        buildPaletteChips(preset),
        buildDetailHeading(_("Layout & Typography")),
        buildLayoutRows(preset.preview.layout || {}, typography),
      ];

      const presetShortcuts = buildShortcutList(
        preset,
        preset.preview.toolbar,
        preset.preview.layout || {},
      );
      if (presetShortcuts) body.push(...presetShortcuts);

      if (needsFontDownload(typography))
        body.push(
          E(
            "p",
            { class: "aurora-store-sc-note" },
            _(
              "This preset uses a downloaded typeface. The router fetches it once after applying; until then the text falls back to the built-in font.",
            ),
          ),
        );

      body.push(
        E(
          "p",
          { class: "aurora-store-dt-foot" },
          _(
            "Applying replaces the shortcuts above and removes the logo, icons and backgrounds the current theme brought with it. Images you uploaded yourself stay as they are.",
          ),
        ),
      );

      renderDrawer([
        buildPanes(paletteOf(preset), previewOpts(preset)),
        E("div", { class: "aurora-store-drawer-body" }, body),
        drawerFoot(_("Apply"), () => confirmBuiltinApply(preset), current),
      ]);
    };

    const openMineDrawer = (item) => {
      const preview = item.preview || {};
      renderDrawer([
        buildPanes(paletteOf(item), previewOpts(item)),
        E("div", { class: "aurora-store-drawer-body" }, [
          E("h3", { style: "margin:0 0 0.3em;" }, [
            document.createTextNode(_("My configuration")),
          ]),
          E(
            "p",
            { class: "aurora-store-dt-desc" },
            modified
              ? _("The look this router is wearing right now.")
              : _(
                  "How this router looked before you applied a theme from the store.",
                ),
          ),
          buildDetailHeading(_("Colors")),
          buildPaletteChips(item),
          buildDetailHeading(_("Layout & Typography")),
          buildLayoutRows(preview.layout || {}, preview.typography || {}),
        ]),
        drawerFoot(_("Apply"), () => confirmRestore(), modified),
      ]);
    };

    const renderDrawerLoadError = () => {
      if (!rootEl.classList.contains("aurora-store-open")) return;
      renderDrawer([
        E("div", { class: "aurora-store-drawer-body" }, [
          E("p", {}, _("Unable to load this theme right now. Please try again.")),
        ]),
        E("div", { class: "aurora-store-drawer-foot" }, [
          E("button", { type: "button", class: "btn", click: closeDrawer }, _("Close")),
        ]),
      ]);
    };

    const openOnlineDrawer = (id) => {
      renderDrawer([
        E("div", { class: "aurora-store-drawer-body" }, [
          E("p", { class: "spinning" }, _("Loading theme details…")),
        ]),
      ]);
      L.resolveDefault(hubApi.callHubGet(id), null)
        .then((res) => {
          if (!rootEl.classList.contains("aurora-store-open")) return;
          if (!res || res.result !== 0 || !res.data) {
            renderDrawerLoadError();
            return;
          }
          const item = res.data;
          renderDrawer([
            buildPanes(paletteOf(item), previewOpts(item)),
            E("div", { class: "aurora-store-drawer-body" }, [buildDetailBody(item)]),
            drawerFoot(_("Apply"), () => confirmOnlineApply(item), isCurrentOnline(item)),
          ]);
        })
        .catch(renderDrawerLoadError);
    };

    // ------------------------------------------------------------------
    // Cards

    const buildBadge = (label, extraClass) =>
      E("span", { class: "aurora-store-badge " + (extraClass || "") }, label);

    // 内置卡和社区卡画的是同一个东西,只是数据来源不同。两个各自为政的构造器
    // 已经漂移过一次 —— 社区卡长出了徽章而内置卡没有 —— 所以只留一个。
    const buildCard = (model) => {
      const prev = E("div", { class: "aurora-store-prev" }, [
        buildDuo(model.palette, model.opts),
        E("span", { class: "aurora-store-dots" }, [buildDotRow(model.palette)]),
        E("div", { class: "aurora-store-acts" }, [
          E(
            "button",
            {
              type: "button",
              class: "btn cbi-button-action",
              click: (ev) => {
                ev.stopPropagation();
                model.apply();
              },
            },
            model.current ? _("Re-apply") : _("Apply"),
          ),
        ]),
      ]);
      if (model.current) prev.appendChild(buildCurrentPin());

      const nm = E("div", { class: "aurora-store-nm" }, [
        document.createTextNode(model.name),
      ]);
      if (model.badge) nm.appendChild(model.badge);
      if (model.glyphs) nm.appendChild(model.glyphs);

      return E(
        "div",
        {
          class: "aurora-store-card" + (model.current ? " current" : ""),
          click: model.open,
        },
        [
          prev,
          E("div", { class: "aurora-store-meta" }, [
            nm,
            E("div", { class: "aurora-store-ft" }, [
              E("span", { style: "word-break:break-all;" }, [
                document.createTextNode(model.author),
              ]),
              E("span", { class: "dl" }, [document.createTextNode(model.right)]),
            ]),
          ]),
        ],
      );
    };

    // 内置卡不带 "Built-in" 徽章:它上方的分区标题已经写着"内置",而每张卡
    // 再重复一遍就是拿掉一行密度换零信息。徽章那个样式类留着,抽屉还在用。
    //
    // 缩略图画的是预设自己的导航形态,glyph 行出的是它自己的字体和圆角 ——
    // 内置预设现在带的是一整套外观,而不是一组色值,卡片必须让人在点进去之前
    // 就看得出这一点。
    const buildBuiltinCard = (preset) => buildCard({
      name: preset.label,
      author: "Aurora",
      right: _("Works offline"),
      palette: paletteOf(preset),
      opts: previewOpts(preset),
      badge: null,
      glyphs: buildCardGlyphs(preset),
      current: isCurrentBuiltin(preset),
      open: () => openBuiltinDrawer(preset),
      apply: () => confirmBuiltinApply(preset),
    });

    const buildOnlineCard = (item) => buildCard({
      name: item.name || _("Untitled theme"),
      author: item.author || _("Anonymous"),
      right: formatDownloads(item.downloads),
      palette: paletteOf(item),
      opts: previewOpts(item),
      // 只有 approved 才是「真的带着素材」。pending 已经被商店列表挡在外面,
      // 而 rejected 的图片已经被删干净了 —— 这两种状态下的徽章都是空头支票。
      badge:
        item.assets_status === "approved" ? buildBadge(_("Includes assets")) : null,
      glyphs: buildCardGlyphs(item),
      current: isCurrentOnline(item),
      open: () => openOnlineDrawer(item.id),
      apply: () => quickApplyOnline(item.id),
    });

    // ------------------------------------------------------------------
    // My configuration
    //
    // 一个槽位,两个时刻。改过 -> 这张卡就是屏幕上正在发生的样子;没改过 ->
    // 它是被商店主题盖掉之前你自己那份。「备份」和「我的配置」本来就是同一个
    // 东西 —— 你被别人的主题盖掉之前的样子 —— 所以它们共用这一张卡,回滚也
    // 就不再是一套要理解的机制,只是把它点回来。

    // 当前 uci 投影成一行 preview,与 presets.json 的行、与 hub 列表行同一个
    // 形状,于是 paletteOf/navOf/tileEntriesFor 读它和读那两种用的是同一套访问
    // 器。三种卡,一套访问器,同一个外观不可能被画成两个样子。
    const currentPreview = () => ({
      colors: SWATCH_KEYS.reduce((acc, key) => {
        ["light", "dark"].forEach((mode) => {
          acc[mode + "_" + key] =
            uci.get("aurora", "theme", mode + "_" + key) || "";
        });
        return acc;
      }, {}),
      layout: {
        nav_type: currentNav,
        struct_radius_base:
          uci.get("aurora", "theme", "struct_radius_base") || "",
      },
      typography: {
        struct_font_sans: uci.get("aurora", "theme", "struct_font_sans") || "",
        struct_font_mono: uci.get("aurora", "theme", "struct_font_mono") || "",
      },
    });

    const mineItem = () => {
      if (!modified && !backupPreview) return null;
      return { preview: modified ? currentPreview() : backupPreview };
    };

    const buildMineModel = () => {
      const item = mineItem();
      if (!item) return null;
      return {
        name: _("My configuration"),
        author: _("On this router only"),
        right: modified ? _("In use") : _("Not in use"),
        palette: paletteOf(item),
        opts: previewOpts(item),
        badge: null,
        glyphs: buildCardGlyphs(item),
        current: modified,
        open: () => openMineDrawer(item),
        apply: () => confirmRestore(),
      };
    };

    const buildMineGrid = () => {
      const model = buildMineModel();
      if (!model) return null;
      return E("div", { class: "aurora-store-grid" }, [buildCard(model)]);
    };

    // 同一份配置,两种画法,按它在哪一页出场。
    //
    // 「全部」页上它是可浏览的一组里的一张卡(buildMineGrid),和内置、社区
    // 那两组同一种形状。「我的」页上它是主角,所以摊成一条横幅:一张 252px
    // 的卡孤零零待在一个为 N 件作品准备的 auto-fill 网格里,后面拖着几格空白
    // —— 而这一格永远只有一件,因为它就是当前 uci 的投影。
    //
    // 横幅换来的宽度不是留白,是清单:发出去到底带什么,连体积一起。那份清单
    // 直接调 shareManifestRows(),发布面板用的是同一个函数 —— 不复制,否则以
    // 后加一项配置要改两处,两处必然会长歪。
    const buildMineBanner = () => {
      const model = buildMineModel();
      if (!model) return null;

      const prev = E("div", { class: "aurora-store-prev" }, [
        buildDuo(model.palette, model.opts),
        E("span", { class: "aurora-store-dots" }, [buildDotRow(model.palette)]),
      ]);
      if (model.current) prev.appendChild(buildCurrentPin());

      const nm = E("div", { class: "aurora-store-nm" }, [
        document.createTextNode(_("My configuration")),
        E(
          "span",
          { class: "aurora-store-pill " + (modified ? "ok" : "") },
          modified ? _("In use") : _("Not in use"),
        ),
      ]);
      if (model.glyphs) nm.appendChild(model.glyphs);

      // 主动作跟着这条横幅代表的东西走,不是跟着按钮的可用性走。改过 ->
      // 它就是屏幕上正在发生的样子,发布发的就是它。没改过 -> 它是被商店
      // 主题盖掉之前那份备份,而 build_share_payload 打包的是当前 uci,不是
      // 这张预览 —— 那时"发布"会发出一份和画面上不符的东西,所以这里根本
      // 不给这个按钮,而不是把它置灰了事。
      const acts = modified
        ? [
            E(
              "button",
              {
                type: "button",
                class: "btn cbi-button-action important",
                click: () => openSharePanel(),
              },
              _("Share to the store"),
            ),
            E(
              "button",
              { type: "button", class: "cbi-button", click: () => model.open() },
              _("Details"),
            ),
          ]
        : [
            E(
              "button",
              {
                type: "button",
                class: "btn cbi-button-action important",
                click: () => confirmRestore(),
              },
              _("Apply"),
            ),
            E(
              "button",
              { type: "button", class: "cbi-button", click: () => model.open() },
              _("Details"),
            ),
          ];

      return E("div", { class: "aurora-store-share aurora-store-mine" }, [
        E("div", { class: "aurora-store-share-prev" }, [prev]),
        E("div", {}, [
          nm,
          E(
            "p",
            { class: "sum" },
            modified
              ? _("The look this router is wearing right now.")
              : _("How this router looked before you applied a theme from the store."),
          ),
          // 抽屉里那排「随附内容」用的同一个 buildTiles。清单本身来自
          // shareManifestRows() —— 发布面板的那一份,一字不差,所以横幅上
          // 写着要发什么,点下去发的就是什么。
          buildTiles(
            shareManifestRows().map((row) => ({
              glyph: "·",
              label: row.label,
              meta: row.detail,
              title: row.label + " — " + row.detail,
            })),
          ),
        ]),
        E("div", { class: "acts" }, acts),
      ]);
    };

    // ------------------------------------------------------------------
    // My shares

    const mySharesEl = E("div", { id: "aurora-hub-my-shares" });

    // One request carries both halves of the answer: who this router
    // publishes as, and what it has published.
    // hub_me 是本页唯一还走 ubus 的网络调用 —— device_token 是 0600 的写凭证
    // (hub_share/hub_update/hub_delete 都靠它认证),不下发到浏览器。整条链路
    // 实测约 0.9s,其中 ubus 只占 0.09s,其余全是路由器到 hub 那次不可复用的
    // TLS 握手加 205ms 跨太平洋 RTT。所以结果要落缓存:下次打开页面由缓存先
    // 画,这一次往返就不再挡在首屏前面。
    //
    // 失败时刻意什么都不做。原先是 applyMe(null),而 applyMe 会把 myShares
    // 置空 —— 断网的用户会眼看着自己已发布的作品从界面上消失。保留上一帧才
    // 是诚实的:我们只是没拿到新数据,不是作品没了。
    const refreshMyShares = () =>
      L.resolveDefault(hubApi.callHubMe(), null).then((res) => {
        if (res && res.result === 0) {
          // 失败时刻意不置 myLoaded:一台冷启动就断网的路由器,我们并不知道
          // 它有没有身份 —— 画那张"还没有创作者身份"的卡就是替 hub 编答案。
          myLoaded = true;
          myFailed = false;
          hubApi.meCache.set(res.data);
          applyMe(res.data);
        } else {
          myFailed = true;
          // 保留上一帧的作品,但这一帧要重画:没有上一帧时它是"连不上 + 重试",
          // 不是空态。
          renderMyShares(myShares);
        }
        // 身份卡是 renderContent 画的,而这次请求正是它等的那份数据 —— 加载态
        // 与空态的切换只有在这里重画才看得见。
        if (state.tab === "mine") renderContent();
      });

    const applyMe = (data) => {
      // 缓存那一帧同样算"已加载":它是真数据,只是旧的。首屏靠它立刻成型,
      // 不该被自己的 spinner 盖住。
      if (data) myLoaded = true;
      profile = {
        id: (data && data.id) || null,
        nickname: (data && data.nickname) || null,
      };
      renderMyShares((data && data.configs) || []);
    };

    // An update rebuilds and re-sends the whole configuration -- logo, login
    // background, site and app icons, shortcuts included -- so it shows the
    // same manifest the publish panel does instead of a bare one-liner.
    // "更新"的意思是用工作台当前这套配置替换掉商店里的它 —— 它和发布是同一
    // 件事,只差一个目标。所以这里不再弹一个跟当前配置八竿子打不着的确认框,
    // 而是把人送回同一张表单,那条分享已经选中、名字和描述已经填好。一套 UI,
    // 两个入口。
    const openUpdateForm = (item) => {
      shareTarget = item.id;
      shareOpen = true;
      nameInput.value = item.name || "";
      descInput.value = item.description || "";
      renderContent();
    };

    // 同一张面板的另一个入口,来自「我的配置」横幅。openUpdateForm 进来时
    // 选中了一条已有分享("用当前配置替换它"),这里什么都不选("发一份新的")。
    //
    // 这一页此前一个发布入口都没有 —— studio.js 的注释记着为什么:页头按钮、
    // 面板标题、空态卡按钮三个入口同时在场,说的都是同一句话,于是一起删掉了。
    // 这次只加回来一个,而且挂在被发布的那个对象上。工作台那个入口保留,两处
    // 落到同一张表单。
    const openSharePanel = () => {
      shareTarget = "";
      shareOpen = true;
      nameInput.value = "";
      descInput.value = "";
      renderContent();
    };

    // btn 是发起这次删除的那一行的 Delete 键:确认框关掉之后,hub_delete 加上
    // 随后的 hub_me 还要走两趟网络,而这两趟里屏幕上原本什么都不会变。
    const confirmDeleteShare = (item, btn) => {
      // Static message, deliberately not interpolating item.name: asset-upload's
      // confirmDelete renders opts.message as a bare E() child, which LuCI can
      // route through innerHTML, and the hub config name is attacker-controlled
      // free text (the hub only strips control characters).
      assetUpload
        .confirmDelete({
          title: _("Delete Share"),
          message: _("Delete this shared configuration from the theme store?"),
        })
        .then((confirmed) => {
          if (!confirmed) return;
          return withBusy(
            btn,
            L.resolveDefault(hubApi.callHubDelete(item.id), null).then((res) => {
              if (res && res.result === 0) {
                ui.addNotification(null, E("p", {}, _("Deleted.")), "info");
              } else {
                ui.addNotification(
                  null,
                  E("p", {}, deleteErrorMessage(res && res.error)),
                  "warning",
                );
              }
              // 失败也要重读一次。invalid_id 说的是"商店那边已经没有这件
              // 作品了",此时留着那一行就是把用户再送回同一个 404。
              return refreshMyShares();
            }),
          );
        });
    };

    // 只在需要作者做点什么、或者需要解释一个反常结果时才出声。none 和
    // approved 是正常态 —— 给正常态也配一行字,列表就变成一片噪音,真正
    // 要紧的那两行反而沉进去了。
    const reviewNoteFor = (status) => {
      if (status === "pending")
        return {
          text: _("In review — appears in the store once its images are approved."),
          color: "var(--text-muted)",
        };
      if (status === "rejected")
        return {
          text: _("Images not approved — colours and layout still work. Swap the image, then update."),
          color: "var(--warning)",
        };
      return null;
    };

    const buildMyShareRow = (item) => {
      const updateBtn = E(
        "button",
        {
          type: "button",
          class: "cbi-button",
          click: () => openUpdateForm(item),
        },
        _("Update with current configuration"),
      );
      const deleteBtn = E(
        "button",
        {
          type: "button",
          class: "cbi-button cbi-button-remove",
          click: () => confirmDeleteShare(item, deleteBtn),
        },
        _("Delete"),
      );

      // The action cell is `td.cbi-section-actions` wrapping a single <div>,
      // which is the shape LuCI's own TableSection emits. Under the mobile
      // breakpoint every theme gives that cell the whole row width and lets
      // the buttons inside it wrap. It used to be `td center` with
      // white-space:nowrap, which pinned "Update with current configuration"
      // and "Delete" onto one unbreakable line: on a 390px phone the row ran
      // to 748px and Delete sat off the right edge of the screen.
      //
      // Deliberately no data-title on the two data cells. Themes hide
      // `.tr.table-titles` on a phone and reprint the column name from that
      // attribute, which is worth it when a bare cell would be ambiguous --
      // here "Nord Midnight" and "128 downloads" already say what they are,
      // and a "Name"/"Downloads" line above each would only stutter.
      // 状态挂在名字底下,不占一列:这张表刚在 390px 上修过溢出,第四列会让
      // 它重演。而状态本来就是在说这一件作品,贴着它的名字最省一次目光移动。
      // 一行色点走在名字前面。/api/v1/me 现在带回和商店列表同一份 preview,
      // 所以这几个色值和别人在商店里看到的这件作品是同一批 —— 作者不必靠
      // 名字回忆哪件是哪件。
      const nameCell = E("td", { class: "td", style: "word-break:break-word;" }, [
        E(
          "span",
          { style: "display:inline-flex;vertical-align:middle;margin-right:8px;" },
          [buildDotRow(paletteOf(item))],
        ),
        document.createTextNode(item.name || _("Untitled theme")),
      ]);

      // 被下架的那一行:它不是错误,是这件作品此刻唯一的真相,而这里是作者
      // 唯一会被告知的地方 —— 公开的浏览接口按设计不会再列出它。
      //
      // 不给按钮,两个都不给。更新一件已经不在商店里的作品没有意义;而删除
      // 走的 hub_delete 要求 status='active'(见 hub 的 requireOwnedConfig),
      // 对着已下架的调过去只会拿到 404,而 404 在 shell 那边只能报成"连不上
      // 商店" —— 那正是这张表以前那个"删了还在"的老毛病的后半段。
      const takenDown = item.status === "removed";
      if (takenDown) {
        nameCell.appendChild(
          E(
            "div",
            { style: "margin-top:2px;font-size:0.84em;color:var(--warning);" },
            _("Taken down — no longer in the store. Nothing you can do from here."),
          ),
        );
      } else {
        const note = reviewNoteFor(item.assets_status);
        if (note) {
          nameCell.appendChild(
            E(
              "div",
              { style: "margin-top:2px;font-size:0.84em;color:" + note.color + ";" },
              note.text,
            ),
          );
        }
      }

      return E("tr", { class: "tr" }, [
        nameCell,
        E("td", { class: "td", style: "color:var(--text-muted);" }, [
          document.createTextNode(formatDownloads(item.downloads)),
        ]),
        E("td", { class: "td cbi-section-actions" }, [
          E("div", {}, takenDown ? [] : [updateBtn, " ", deleteBtn]),
        ]),
      ]);
    };

    let myShares = [];

    // hub_me 回来过没有,以及上一次是不是失败的。首屏之所以要分这两个状态:
    // 没有它们,一台还在等 hub_me 的路由器画的是"还没有分享过" —— 一句在
    // 数据到达前就说出口的、可能是假的话。
    let myLoaded = false;
    let myFailed = false;

    // Whoever this router publishes as. A null nickname means the creator
    // account exists but has never been named.
    let profile = { id: null, nickname: null };

    let keySaved = loadData.keySaved;

    // A Blob and an object URL rather than a data: URI -- the key never
    // becomes part of a URL that could be kept in history.
    const downloadKey = (key) => {
      const blob = new Blob([key + "\n"], { type: "text/plain" });
      const url = URL.createObjectURL(blob);
      const a = E("a", { href: url, download: "aurora-creator-key.txt" });
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    };

    // LuCI 只从 http://192.168.1.1 提供,那不是 secure context,所以
    // navigator.clipboard 在这个页面上恒为 undefined —— 真正会跑的是下面
    // execCommand 那条。现代调用留在前面,只为极少数套了 https 反代的装法。
    const copyText = (text) => {
      if (navigator.clipboard && navigator.clipboard.writeText)
        return navigator.clipboard.writeText(text);

      return new Promise((resolve, reject) => {
        const scratch = E("textarea", {
          style: "position:fixed;top:-1000px;left:-1000px;opacity:0;",
        });
        scratch.value = text;
        document.body.appendChild(scratch);
        scratch.select();
        let ok = false;
        try {
          ok = document.execCommand("copy");
        } catch (e) {
          ok = false;
        }
        document.body.removeChild(scratch);
        if (ok) resolve();
        else reject();
      });
    };

    const KEY_MASK = "•".repeat(64);

    // 返回 promise:调用方(身份卡上那个按钮)拿它做 busy —— 取密钥要过一次
    // ubus,弹窗在那之后才出现,中间这段静默正是用户会再点一次的地方。
    const backupKeyPrompt = () =>
      L.resolveDefault(hubApi.callHubExportKey(), null).then((res) => {
        if (!res || res.result !== 0 || !res.key) {
          ui.addNotification(
            null,
            E("p", {}, _("Couldn't read your identity. Please try again.")),
            "warning",
          );
          return;
        }

        // rpcd already recorded the flag when it handed the key over; this
        // view is browse-only and has no uci write path of its own.
        keySaved = true;

        // 默认遮住。这串东西等同于账号密码,不该因为"我只是想看看这个弹窗长
        // 什么样"就明晃晃地摊在旁边的人也看得见的屏幕上。
        const keyEl = E(
          "code",
          {
            style:
              "flex:1;min-width:0;word-break:break-all;font-size:0.85em;line-height:1.5;",
          },
          [document.createTextNode(KEY_MASK)],
        );
        let shown = false;

        const toggleBtn = E(
          "button",
          { type: "button", class: "cbi-button" },
          _("Show"),
        );
        const reveal = () => {
          shown = true;
          keyEl.textContent = res.key;
          toggleBtn.textContent = _("Hide");
        };
        toggleBtn.addEventListener("click", () => {
          if (shown) {
            shown = false;
            keyEl.textContent = KEY_MASK;
            toggleBtn.textContent = _("Show");
          } else {
            reveal();
          }
        });

        const copyBtn = E(
          "button",
          { type: "button", class: "cbi-button" },
          _("Copy"),
        );
        copyBtn.addEventListener("click", () => {
          copyText(res.key).then(
            () => {
              copyBtn.textContent = _("Copied");
              window.setTimeout(() => {
                copyBtn.textContent = _("Copy");
              }, 1500);
            },
            () => {
              // 复制不成不能是死路 —— 把身份亮出来,至少还能手动选中。
              reveal();
              ui.addNotification(
                null,
                E(
                  "p",
                  {},
                  _("Couldn't copy. The identity is shown above — select it and copy it manually."),
                ),
                "warning",
              );
            },
          );
        });

        ui.showModal(_("Back up your creator identity"), [
          E(
            "p",
            {},
            _("This text is your identity. Anyone who has it can publish under your name and delete what you have shared — don't post it anywhere public."),
          ),
          E("div", { class: "aurora-store-keybox" }, [keyEl, toggleBtn]),
          E(
            "p",
            { style: "color:var(--text-muted);font-size:0.85em;margin:0;" },
            _("It exists only on this router. Reflashing without keeping settings erases it."),
          ),
          E("div", { class: "right", style: "margin-top:1em;" }, [
            copyBtn,
            " ",
            E(
              "button",
              {
                type: "button",
                class: "btn cbi-button-action important",
                click: () => {
                  downloadKey(res.key);
                  ui.hideModal();
                  renderContent();
                },
              },
              _("Download backup file"),
            ),
            " ",
            E(
              "button",
              { type: "button", class: "cbi-button", click: () => ui.hideModal() },
              _("Close"),
            ),
          ]),
        ]);
      });

    // "我的分享" 顶上的常驻卡片:这台路由器以谁的名义发布,身份备没备份,以及
    // 身份的几个动作都在这里。
    //
    // 它取代了原来那条 keybar。keybar 的毛病不在样式,在于 profile.id 为空时
    // 整条不渲染 —— 于是一台全新路由器看不到"备份"那一半。
    //
    // 一张卡两个状态,而不是两张卡:没有身份时它照画,只是名字换成"还没有创作
    // 者身份",动作只剩「恢复…」。以前这里 return null,于是一台刚刷好的路由器
    // 在「我的」页上只有一句"还没有分享过" —— 而带着备份文件从旧路由器过来的
    // 人,恰恰要的就是这一屏上的恢复入口,却一个入口都没有。
    //
    // 加载未回来之前仍然返回 null:那时 profile 是空的,画空态就是先撒一次谎
    // 再纠正。这一小段等待由下面 mySharesEl 里的 spinner 一并说了。
    //
    // 改名也搬到了这里。它以前只挂在发布面板内部那个 "Publish as" 字段的
    // Change 按钮上 —— 不点开发布面板就找不到,等于"想改个名得先假装去发个布"。
    const buildIdentityCard = () => {
      if (!myLoaded) return null;

      const nameRow = [];
      const acts = [];
      let meta;
      // 首字母做头像。昵称可以是任意 Unicode,取第一个 code point 而不是第一个
      // UTF-16 码元 —— 否则一个 emoji 昵称会被切成半个代理对,画出一个方块。
      let initial = "#";

      if (!profile.id) {
        nameRow.push(
          E("strong", { style: "color:var(--text-muted);" }, [
            document.createTextNode(_("No creator identity yet")),
          ]),
        );
        meta = _("Created the first time you publish — or restore one you backed up.");
        // 唯一的动作,所以是实心的那个:这张卡此刻只剩一件事可做。
        acts.push(
          E(
            "button",
            {
              type: "button",
              class: "btn cbi-button-action",
              click: () => restoreIdentityPrompt(),
            },
            _("Restore…"),
          ),
        );
      } else {
        if (profile.nickname) {
          nameRow.push(
            E("strong", {}, [document.createTextNode(profile.nickname)]),
          );
          initial = Array.from(profile.nickname)[0];
        } else {
          nameRow.push(
            E("strong", { style: "color:var(--text-muted);" }, [
              document.createTextNode(_("Not named yet")),
            ]),
          );
        }
        nameRow.push(
          E("span", { class: "hid" }, [document.createTextNode("#" + profile.id)]),
          E(
            "span",
            { class: "aurora-store-pill " + (keySaved ? "ok" : "risk") },
            keySaved ? _("Backed up") : _("Not backed up"),
          ),
        );
        meta = _("Signs everything you share. It lives only on this router.");
        // 身份的三个动作全在这一处。备份是实心的那个(没备份时),改名和
        // 恢复是文字链 —— 它们不是这张卡要人做的事,只是要人找得到的事。
        //
        // 「恢复」以前有两个入口:折叠说明里一条,空态引导卡里又一条,同屏
        // 可见,指向同一个对话框。空态卡整张删掉了,说明里那条也删了,只剩
        // 这一个。
        acts.push(
          E(
            "button",
            {
              type: "button",
              class: keySaved ? "cbi-button" : "btn cbi-button-action",
              click: (ev) => withBusy(ev.currentTarget, backupKeyPrompt()),
            },
            _("Back up identity"),
          ),
          " ",
          E(
            "button",
            { type: "button", class: "cbi-button", click: () => promptRename() },
            _("Rename"),
          ),
          " ",
          E(
            "button",
            { type: "button", class: "lnk", click: () => restoreIdentityPrompt() },
            _("Restore…"),
          ),
        );
      }

      return E("div", {}, [
        E("div", { class: "aurora-store-idcard" }, [
          E("div", { class: "av" }, [document.createTextNode(initial)]),
          E("div", { class: "who" }, [
            E("div", { class: "nm" }, nameRow),
            E("div", { class: "meta" }, [document.createTextNode(meta)]),
          ]),
          E("div", { class: "acts" }, acts),
        ]),
        E("details", { class: "aurora-store-why" }, [
          E("summary", {}, _("What is this? Where did it come from?")),
          E("p", { style: "margin:0;" }, [
            document.createTextNode(
              _("Created automatically the first time you publish — no sign-up, no password. It decides which configurations in the store are yours, and who can change or remove them. Backing it up saves an identity backup file; import that file after a reflash, or on a new router, and your work comes back to you."),
            ),
          ]),
        ]),
      ]);
    };

    const KEY_RE = /^[a-f0-9]{64}$/;

    const restoreIdentityPrompt = () => {
      // The share panel's fields get their width from .aurora-store-field; this
      // one lives in a modal, where a default-sized textarea leaves a 64-hex
      // key wrapping inside a box narrower than the dialog holding it.
      const input = E("textarea", {
        class: "cbi-input-textarea",
        rows: 2,
        style: "width:100%;box-sizing:border-box;",
      });
      const err = E("p", {
        style: "color:var(--danger);font-weight:600;display:none;margin:0.6em 0 0;",
      });

      // One parse path: the file button only fills the box. The input itself is
      // hidden behind a label -- the browser's own "no file selected" chrome
      // says nothing a user of this dialog needs.
      const picker = E("input", { type: "file", accept: ".txt,text/plain" });
      picker.style.display = "none";
      picker.addEventListener("change", () => {
        const file = picker.files && picker.files[0];
        if (!file) return;
        file.text().then((text) => {
          input.value = text.trim();
        });
      });
      const fileBtn = E(
        "label",
        { class: "cbi-button aurora-store-filebtn" },
        [document.createTextNode(_("Choose backup file…")), picker],
      );

      // 返回 promise:导入加上随后那次 hub_me 是两趟往返,确认键要 busy 到
      // 两趟都回来为止 —— 见 buildConfirmActions。
      const commit = () => {
        const key = input.value.trim().toLowerCase();
        if (!KEY_RE.test(key)) {
          err.textContent = _("That doesn't look like a creator identity.");
          err.style.display = "block";
          return;
        }
        return L.resolveDefault(hubApi.callHubImportKey(key), null).then((res) => {
          if (!res || res.result !== 0) {
            err.textContent = _("Couldn't restore that identity. Check it and try again.");
            err.style.display = "block";
            return;
          }
          ui.hideModal();
          // 换账号了 —— 缓存里那份档案属于上一个 key。先清掉再刷新,否则
          // "导入成功、随后 hub_me 失败"会把上一个账号的作品留在界面上,
          // 而 Task 2 之后失败路径不再自行清空。
          hubApi.meCache.clear();
          myLoaded = false;
          applyMe(null);
          return refreshMyShares().then(() => {
            keySaved = true;
            ui.addNotification(
              null,
              E(
                "p",
                {},
                myShares.length
                  ? _("Restored. What you shared before is back under this identity.")
                  : _("Restored."),
              ),
              "info",
            );
            renderContent();
          });
        });
      };

      const body = [
        E(
          "p",
          {},
          _("Paste the identity you backed up, or pick the backup file you downloaded. What you shared before comes back under this router."),
        ),
        input,
        E("div", { style: "margin-top:0.6em;" }, [fileBtn]),
        err,
      ];

      // Replacing an identity that still owns published work is unrecoverable,
      // so it gets said out loud before the button that does it.
      //
      // 这里曾经还挂着一个「先备份当前身份」按钮。备份入口在身份卡上就有一个,
      // 这个框是恢复框 —— 一个对话框只做一件事,警告负责讲后果,不负责再开一
      // 条通往别处的岔路。
      if (myShares.length) {
        body.splice(
          1,
          0,
          E(
            "p",
            { style: "color:var(--danger);" },
            _("This router already has shared configurations of its own. Switching to another identity gives them up for good — back up the current identity first if you still want them."),
          ),
        );
      }

      body.push(buildConfirmActions(commit, _("Restore")));
      ui.showModal(_("Restore your creator identity"), body);
    };

    // The tab keeps the count of what is already published, so the number is
    // readable without opening the tab first.
    const renderMyShares = (items) => {
      // 这里曾经有一句 filter(status !== "removed")。当时商店的软删除让作者
      // 自己删掉的作品继续出现在 /api/v1/me 里,只是 status 变成 removed ——
      // 删成功了、刷新一遍那一行还在,用户再点一次就撞 404。滤掉是对的,代价
      // 是被管理员下架的作品也一起被藏了,作者永远不知道自己被下架过。
      //
      // 现在 hub 那边分得清了(migration 0007 的 removed_by):作者自己删的根本
      // 不再下发,而 status === "removed" 只剩一个意思 —— 被下架。所以这里不再
      // 滤,那一行改由 buildMyShareRow 画成「已下架」。
      myShares = (items || []).filter((item) => item);
      TABS.forEach(renderTabLabel);
      while (mySharesEl.firstChild) mySharesEl.removeChild(mySharesEl.firstChild);

      // 三个"没有表格"的理由,措辞各不相同,因为它们是三件事:问不到、还不
      // 知道、确实没有。文案和转圈都跟社区网格用同一套 —— 同一页上同一种等待
      // 不该长出第二种样子。
      if (myFailed && !myShares.length) {
        mySharesEl.appendChild(
          E("div", { class: "aurora-store-none" }, [
            E("p", { style: "margin:0 0 0.6em;" }, _("Unable to reach the theme store right now.")),
            E(
              "button",
              {
                type: "button",
                class: "cbi-button cbi-button-apply",
                click: (ev) => withBusy(ev.currentTarget, refreshMyShares()),
              },
              _("Retry"),
            ),
          ]),
        );
        return;
      }
      if (!myLoaded) {
        mySharesEl.appendChild(
          E("p", { class: "spinning", style: "padding:1.2em 0.2em;" }, _("Loading…")),
        );
        return;
      }

      if (!myShares.length) {
        // 曾经是一张虚线卡:标题、一段说明、一个"去工作台"按钮,外加第二条
        // "恢复身份"链接。三样东西现在都没有理由存在了 —— 发布入口就在这一
        // 屏上方那条横幅上,身份的恢复入口在身份卡里。剩下要说的只有一句:
        // 这里以后会长出什么。
        mySharesEl.appendChild(
          E(
            "p",
            { class: "aurora-store-none" },
            _("Nothing shared yet. Publish the configuration above and it shows up here."),
          ),
        );
        return;
      }
      mySharesEl.appendChild(
        E("table", { class: "table" }, [
          E("tr", { class: "tr table-titles" }, [
            E("th", { class: "th" }, _("Name")),
            E("th", { class: "th" }, _("Downloads")),
            E("th", { class: "th center" }, ""),
          ]),
          ...myShares.map((item) => buildMyShareRow(item)),
        ]),
      );
      // 这里曾经跟着一句"想再发一套?去工作台发"。它存在的理由是这一页当时
      // 没有发布入口 —— 现在这一屏上方就是那条横幅,再指一次路只是多一行字。
    };

    // ------------------------------------------------------------------
    // Publishing: an inline panel inside "My Shares", not a modal, so the
    // manifest of what actually goes out has room to sit next to the fields.

    // Everything the manifest needs is already in uci -- no extra rpc call.
    const shareManifestRows = () => {
      const rows = [
        { label: _("Colors"), detail: _("Light and dark, 62 values") },
        {
          label: _("Navigation"),
          detail: NAV_TYPE_LABELS[currentNav] || currentNav,
        },
      ];

      // build_share_payload sends spacing and content width alongside the
      // navigation shape, and the detail drawer lists both -- leaving them out
      // here would under-promise right above "Anyone who applies this gets all
      // of it."
      const spacing = uci.get("aurora", "theme", "struct_spacing");
      if (spacing) rows.push({ label: _("Spacing"), detail: spacing });

      const radius = radiusLabel(uci.get("aurora", "theme", "struct_radius_base"));
      if (radius) rows.push({ label: _("Shape"), detail: radius });

      const contentWidth = uci.get(
        "aurora",
        "theme",
        "struct_content_width_centered",
      );
      if (contentWidth)
        rows.push({ label: _("Content Width"), detail: contentWidth });

      const family = firstFontFamily(uci.get("aurora", "theme", "struct_font_sans"));
      const mono = firstFontFamily(uci.get("aurora", "theme", "struct_font_mono"));
      if (family)
        rows.push({
          label: _("Fonts"),
          detail: mono ? family + " · " + mono : family,
        });

      // 上传的字体文件本身也要单独列一行。上面那行只是字体的名字 —— 而这
      // 一行说的是"这份 woff2 会被传上去",带着体积,因为它决定了别人要不要
      // 在自己的路由器上腾出这么多空间。
      sharedFonts.forEach((font) =>
        rows.push({
          label:
            font.slot === "mono" ? _("Mono Font File") : _("Sans Font File"),
          detail: _("Uploaded with the theme, %s").format(
            assetUpload.formatSize(font.size),
          ),
        }),
      );

      // 图片这几行以前只写 "Included"。而对着这张清单要做的决定是「把这套
      // 主题发出去」,对着商店详情页要做的决定是「把它装到我的路由器上」——
      // 两个决定都要看体积,一张 1.8MB 的登录背景和一个 3KB 的 logo 不是一
      // 回事。体积来自 rpcd 的 shared_images:问的是 build_share_payload 打包
      // 时问的同一个函数,所以屏幕上说要发什么,线路上发的就是什么。
      //
      // 两个槽位共用 "Site Icon" 标签、两个共用 "App Icon",所以按标签合并 ——
      // 同一个名字出现两次是错的。合并后的体积是这几个槽位的和。
      const IMAGE_ROW_LABELS = {
        logo_svg: ASSET_LABELS.logo,
        favicon_png: ASSET_LABELS.siteIcon,
        favicon_ico: ASSET_LABELS.siteIcon,
        pwa_icon_192: ASSET_LABELS.appIcon,
        pwa_icon_512: ASSET_LABELS.appIcon,
        login_bg: ASSET_LABELS.loginBg,
        main_bg: ASSET_LABELS.mainBg,
      };
      const imageRows = [];
      sharedImages.forEach((image) => {
        const label = IMAGE_ROW_LABELS[image && image.kind];
        if (!label) return;
        const size = Number(image.size) || 0;
        const existing = imageRows.filter((row) => row.label === label)[0];
        // 超限的不与正常的合并:一行同时说"共 2.1 MB"和"太大发不出去"就没法读
        // 了,而"哪一张太大"正是用户此刻唯一需要知道的事。
        const oversized = image.oversized === true;
        if (existing && existing.oversized === oversized) {
          existing.size += size;
          return;
        }
        imageRows.push({ label: label, size: size, oversized: oversized });
      });
      imageRows.forEach((row) =>
        rows.push({
          label: row.label,
          detail: row.oversized
            ? _("Too large to share (%s; the store's limit is %s)").format(
                assetUpload.formatSize(row.size),
                assetUpload.formatSize(MAX_SHARED_IMAGE),
              )
            : _("Included, %s").format(assetUpload.formatSize(row.size)),
        }),
      );

      // Anonymous toolbar_item sections have no stable index, so the array is
      // filtered and counted rather than iterated by position.
      const shortcuts = Math.min(
        (uci.sections("aurora", "toolbar_item") || []).filter(isSharedToolbarItem)
          .length,
        MAX_SHARED_TOOLBAR_ITEMS,
      );
      if (shortcuts)
        rows.push({
          label: _("Toolbar"),
          detail:
            shortcuts === 1
              ? _("1 shortcut")
              : _("%d shortcuts").format(shortcuts),
        });

      // 快捷方式的图标以前只是个文件名跟着走,而那个文件只存在于这台路由器
      // 上 —— 别人应用完,工具栏上就是一排空框。现在字节也跟着走,所以这里
      // 要把它当成一份真的资产来交代:发几个、多大。
      //
      // 发不出去的那些单独说。图标只收 PNG 和 SVG(审核台只有这两条清洗
      // 路径),超过 256 KiB 的也不发 —— 12 个槽位按图片的上限放行,光图标
      // 就能把审核请求撑爆。这两种情况都不是错误,但沉默地少发一个图标,
      // 用户只会在别人的截图里发现它没了。
      const shippedIcons = sharedToolbarIcons.filter((icon) => icon && icon.shipped);
      const droppedIcons = sharedToolbarIcons.filter((icon) => icon && !icon.shipped);
      if (shippedIcons.length)
        rows.push({
          label: _("Shortcut Icons"),
          detail: _("%d included, %s").format(
            shippedIcons.length,
            assetUpload.formatSize(
              shippedIcons.reduce((sum, icon) => sum + (Number(icon.size) || 0), 0),
            ),
          ),
        });
      if (droppedIcons.length)
        rows.push({
          label: _("Shortcut Icons"),
          detail: _("%d not shared — only PNG and SVG under %s travel with a theme").format(
            droppedIcons.length,
            assetUpload.formatSize(MAX_SHARED_TOOLBAR_ICON),
          ),
        });

      return rows;
    };

    // Shared by the publish panel and the update confirmation: an update runs
    // the very same payload build, so it has to say the same thing about what
    // leaves the router.
    const buildManifestTable = () =>
      E("table", { class: "table" }, [
        E("tr", { class: "tr table-titles" }, [
          E("th", { class: "th" }, _("Content")),
          E("th", { class: "th" }, _("Details")),
        ]),
        // Same call as buildMyShareRow: no data-title. Every row here is
        // already a label facing its own value ("Colors" -> "Light and dark,
        // 62 values"), so reprinting "Content"/"Details" above each of the
        // eleven rows on a phone is eleven stutters and no information.
        ...shareManifestRows().map((row) =>
          E("tr", { class: "tr" }, [
            E("td", { class: "td" }, [document.createTextNode(row.label)]),
            E("td", { class: "td", style: "color:var(--text-muted);" }, [
              document.createTextNode(row.detail),
            ]),
          ]),
        ),
      ]);

    // 意图优先,状态兜底。用户上一秒刚在工作台点了"分享到商店",这句话是他
    // 亲口说的;跳过来给他一张列表,等于把它丢掉,还得让他自己再找一次入口。
    // "有没有作品"是历史状态,不该盖掉"他现在要干什么" —— 所以带意图进来
    // 永远是表单,不判断。没有意图才看状态:没作品给路标,有作品给列表。
    //
    // 用 URL 参数而不是 sessionStorage:刷新、回退、收藏行为都可预测。
    const shareIntent =
      new URLSearchParams(window.location.search).get("share") === "1";
    let shareOpen = shareIntent;

    // 空串 = 发布为新的一条;否则是要被这套配置覆盖掉的那条分享的 id。
    //
    // 带意图进来又已经有作品时,只给一张空表单会让人发出第二条几乎一样的
    // 东西 —— 他八成想更新已经发过的那条。而"更新"的语义本来就是"用当前
    // 配置替换商店里的它",起点同样在工作台,所以它和发布共用同一张表单,
    // 只差一个目标。
    let shareTarget = "";

    // The panel is rebuilt on every renderContent() -- a keystroke in the
    // search box, or a list fetch landing late -- so the nodes that hold user
    // state (the three fields, the error line, the button's disabled flag) are
    // created ONCE here and re-parented by buildSharePanel. Constructing them
    // inside the builder silently threw away a half-typed name and description,
    // and handed a mid-flight publish a second, freshly enabled button.
    const nameInput = E("input", {
      type: "text",
      class: "cbi-input-text",
      maxlength: 60,
      placeholder: _("Give it a name"),
    });
    const descInput = E("textarea", {
      class: "cbi-input-textarea",
      rows: 3,
      maxlength: 500,
      placeholder: _("One line about where this configuration fits."),
    });
    // Only ever shown while the creator account has no name yet. Not seeded
    // from anywhere local: the hub owns the name, and a cached copy would go
    // stale the moment it is changed from another browser.
    const nicknameInput = E("input", {
      type: "text",
      class: "cbi-input-text",
      maxlength: 40,
      placeholder: _("The name your shares are signed with"),
    });

    const errEl = E("p", {
      style: "color:var(--danger);font-weight:600;display:none;margin:0 0 0.6em;",
    });

    // 与 errEl 同理:创建一次,由 buildSharePanel 重新挂载。发布过程中面板会
    // 被 renderContent 重建,把节点建在构造函数里会让进度在第一次重绘时归零。
    const progressEl = E("p", {
      style: "color:var(--text-muted);font-size:0.85em;display:none;margin:0 0 0.6em;",
    });

    const showError = (message) => {
      errEl.textContent = message;
      errEl.style.display = "block";
      progressEl.style.display = "none";
    };

    // 复用 ASSET_LABELS 的措辞,免得同一张图在清单里叫"登录背景"、在进度条上
    // 叫另一个名字。
    const ASSET_PROGRESS_LABELS = {
      logo_svg: ASSET_LABELS.logo,
      favicon_png: ASSET_LABELS.siteIcon,
      favicon_ico: ASSET_LABELS.siteIcon,
      pwa_icon_192: ASSET_LABELS.appIcon,
      pwa_icon_512: ASSET_LABELS.appIcon,
      login_bg: ASSET_LABELS.loginBg,
    };
    // 图标的 kind 带着槽位号(toolbar_icon_3),那是个内部编号,不是一个地方。
    // 让它掉进下面那个 `|| info.kind` 的兜底,进度条上就会写着 "正在上传
    // toolbar_icon_3…" —— 这个文件开头那条"机制词永不出现"的规矩说的正是它。
    TOOLBAR_ICON_KINDS.forEach((kind) => {
      ASSET_PROGRESS_LABELS[kind] = _("Shortcut Icons");
    });

    // 一张 1.2MB 的图在慢上行的线路上要传十几秒,而那段时间里页面上唯一会动
    // 的东西就是这一行。没有它,等待读起来就是卡死。
    const renderShareProgress = (info) => {
      progressEl.style.display = "block";
      if (info.phase === "begin") {
        progressEl.textContent = _("Preparing…");
        return;
      }
      if (info.phase === "commit") {
        progressEl.textContent = _("Finishing…");
        return;
      }
      const label = ASSET_PROGRESS_LABELS[info.kind] || info.kind;
      const pct = info.total ? Math.round((info.loaded / info.total) * 100) : 0;
      progressEl.textContent =
        info.count > 1
          ? _("Uploading %s… %d%% (%d/%d)").format(label, pct, info.index, info.count)
          : _("Uploading %s… %d%%").format(label, pct);
    };

    const submitBtn = E(
      "button",
      { type: "button", class: "btn cbi-button-action important" },
      _("Publish"),
    );

    const doSubmit = () => {
      const name = nameInput.value.trim();
      if (!name) {
        showError(_("Please enter a name."));
        return;
      }

      const description = descInput.value.trim();
      const wantedNickname = profile.nickname ? "" : nicknameInput.value.trim();
      if (!profile.nickname && !wantedNickname) {
        showError(_("Choose the name to publish under."));
        return;
      }

      errEl.style.display = "none";
      submitBtn.disabled = true;
      submitBtn.classList.add("spinning");
      // 进度行原先要等第一个资源开始上传才出现,而在那之前还有一次 claim 昵称
      // 的往返 —— 那几秒里按钮已经按不动了,却没有一个字解释为什么。
      renderShareProgress({ phase: "begin" });

      // 三条收尾路径(昵称被拒、发布失败、发布成功刷新完)共用同一个还原。
      const endSubmit = () => {
        submitBtn.disabled = false;
        submitBtn.classList.remove("spinning");
      };

      // Two calls on purpose. The signature is account state, so it is
      // claimed first and the publish itself carries no author at all. If the
      // name turns out to be taken, nothing has been published yet and the
      // user simply picks another.
      const claim = wantedNickname
        ? L.resolveDefault(hubApi.callHubSetNickname(wantedNickname), null).then((res) => {
            const data = (res && res.result === 0 && res.data) || null;
            if (data && !data.error) {
              profile = { id: data.id, nickname: data.nickname };
              return true;
            }
            showError(
              data ? nicknameErrorMessage(data.error) : shareErrorMessage(res && res.error),
            );
            return false;
          })
        : Promise.resolve(true);

      claim.then((claimed) => {
        if (!claimed) {
          endSubmit();
          return;
        }
        hubApi
          .publishCurrentConfig({
            name: name,
            description: description,
            targetId: shareTarget,
            onProgress: renderShareProgress,
          })
          .then((res) => {
            if (res && res.result === 0) {
              // 两句话,两个维度:第一句讲这次发布的结果,第二句讲身份该备份。
              // 它们互不嵌套 —— 合成一条 msgid 的话,任一边多一个分支就要把
              // 另一边的每种说法都重写一遍。
              //
              // 身份那句仍然只在没备份时出现:这是它唯一值得一读的时刻,用户
              // 刚刚获得了一件丢得掉的东西。
              const notice = [
                res.assets
                  ? _("Published. Its images are queued for review — it appears in the store once they are approved.")
                  : _("Published."),
              ];
              if (!keySaved)
                notice.push(
                  _("Your creator identity lives only on this router — back it up so a reflash can't take it."),
                );
              ui.addNotification(
                null,
                notice.map((line) => E("p", {}, line)),
                "info",
              );
              shareOpen = false;
              shareTarget = "";
              // 意图参数留在地址栏里的话,用户刷新一下又撞回一张空表单 —— 而他
              // 刚刚才发布完,这一页现在该给他看的是那件作品。
              if (shareIntent && window.history && window.history.replaceState) {
                window.history.replaceState({}, "", window.location.pathname);
              }
              // The button stays disabled until the panel is off screen --
              // re-enabling it here would leave a live Publish button up for the
              // whole my-shares round trip, and a second click would post the
              // same configuration twice. The draft is cleared at the same time
              // so reopening the panel starts fresh rather than re-offering what
              // was just published.
              refreshMyShares().then(() => {
                nameInput.value = "";
                descInput.value = "";
                nicknameInput.value = "";
                endSubmit();
                renderContent();
              });
            } else {
              endSubmit();
              showError(shareErrorMessage(res && res.error));
            }
          });
      });
    };

    // Identity is asked for once. After that it is shown, not re-typed:
    // re-offering a filled-in box on every publish suggests the signature is
    // per-config, which is exactly what this stopped being.
    //
    // Reached from the identity card only -- see buildIdentityCard.
    const promptRename = () => {
      const input = E("input", {
        type: "text",
        class: "cbi-input-text",
        maxlength: 40,
        value: profile.nickname || "",
      });
      const err = E("p", {
        style: "color:var(--danger);font-weight:600;display:none;margin:0.6em 0 0;",
      });

      ui.showModal(_("Change your name"), [
        E(
          "p",
          {},
          _("This name signs everything you have published, including what is already in the store."),
        ),
        input,
        err,
        buildConfirmActions(() => {
          const next = input.value.trim();
          if (!next) {
            err.textContent = _("Pick a name between 1 and 40 characters.");
            err.style.display = "block";
            return;
          }
          // 返回给 buildConfirmActions 做 busy —— 改名要过 hub,不是本地操作。
          return L.resolveDefault(hubApi.callHubSetNickname(next), null).then((res) => {
            const data = (res && res.result === 0 && res.data) || null;
            if (data && !data.error) {
              ui.hideModal();
              return refreshMyShares().then(renderContent);
            }
            err.textContent = data
              ? nicknameErrorMessage(data.error)
              : shareErrorMessage(res && res.error);
            err.style.display = "block";
          });
        }, _("Save")),
      ]);
    };

    submitBtn.addEventListener("click", doSubmit);

    // Before the account has a name: an input. After: the signature it will
    // carry -- read-only. The short id is shown here (and in the detail
    // drawer) rather than on cards -- names are unique, so a number on every
    // card would be noise, but it is what lets someone prove which "Eamon"
    // they are.
    //
    // Renaming used to hang off a Change button right here, which made this
    // panel the only route to it. It lives on the identity card now, so this
    // field states the signature and nothing else.
    const buildIdentityField = (field) => {
      if (!profile.nickname) return field(_("Publish as"), nicknameInput);

      return E("div", { class: "aurora-store-field" }, [
        E("label", {}, _("Publish as")),
        E("div", {}, [
          E("strong", {}, [document.createTextNode(profile.nickname)]),
          E("span", { style: "color:var(--text-muted);margin-left:0.5em;" }, [
            document.createTextNode("#" + (profile.id || "")),
          ]),
        ]),
      ]);
    };

    // 一件作品都没有时不渲染:零选项的单选组是噪音,而"你还没有作品"这句话
    // 表单标题已经说了。
    const buildTargetPicker = () => {
      if (!myShares.length) return null;

      const row = (value, label, meta) => {
        const input = E("input", {
          type: "radio",
          name: "aurora-share-target",
          value: value,
        });
        input.checked = shareTarget === value;
        input.addEventListener("change", () => {
          shareTarget = value;
          const target = myShares.filter((item) => item.id === value)[0];
          if (target) {
            // 选了更新就把那条的现值填回去 —— 否则用户得凭记忆重打一遍
            // 名字,打错一个字就变成"改名"而不是"更新"。
            nameInput.value = target.name || "";
            descInput.value = target.description || "";
          } else {
            nameInput.value = "";
            descInput.value = "";
          }
          renderContent();
        });
        return E("label", { class: "aurora-store-target-row" }, [
          input,
          E("span", { class: "nm" }, [document.createTextNode(label)]),
          E("span", { class: "mt" }, [document.createTextNode(meta)]),
        ]);
      };

      const rows = [
        row("", _("Publish as a new one"), _("One more piece in the store")),
      ];
      myShares.forEach((item) => {
        rows.push(
          row(
            item.id,
            // 名字来自 hub,是不可信自由文本 —— 走 createTextNode(见 row)。
            _("Replace “%s”").format(item.name || ""),
            item.downloads === 1
              ? _("1 download")
              : _("%d downloads").format(item.downloads || 0),
          ),
        );
      });

      return E("div", { class: "aurora-store-target" }, [
        E("div", { class: "hd" }, _("Where this configuration goes")),
        ...rows,
      ]);
    };

    const buildSharePanel = () => {
      const field = (label, control) =>
        E("div", { class: "aurora-store-field" }, [
          E("label", {}, label),
          control,
        ]);

      const manifestTable = buildManifestTable();

      // 同一颗按钮,两种承诺。文案必须跟着目标走:"发布"和"覆盖掉商店里那条"
      // 是两件事,用同一个词会让人误以为只是多发一条,结果盖掉了自己的作品。
      const targetItem = myShares.filter((item) => item.id === shareTarget)[0];
      while (submitBtn.firstChild) submitBtn.removeChild(submitBtn.firstChild);
      submitBtn.appendChild(
        document.createTextNode(
          targetItem ? _("Replace “%s”").format(targetItem.name || "") : _("Publish"),
        ),
      );

      // 攒数组再返回:一件作品都没有时 buildTargetPicker 返回 null,而 E() 的
      // 子节点数组里混进 null 会抛错。
      const children = [];
      const picker = buildTargetPicker();

      children.push(
        E("div", { class: "aurora-store-share-head" }, [
          // Not "Publish current configuration" any more: this is no longer an
          // entry point that has to name itself, it is the form you already
          // opened. So the title spends its words on what happens next.
          E("div", {}, [
            E("h4", { style: "margin:0;" }, _("Share to the store")),
            E(
              "p",
              { style: "margin:2px 0 0;color:var(--text-muted);font-size:0.84em;" },
              _("Once published, anyone can find it and apply it in one click. You can update or remove it later."),
            ),
          ]),
          E(
            "button",
            {
              type: "button",
              class: "cbi-button",
              click: () => {
                shareOpen = false;
                renderContent();
              },
            },
            _("Cancel"),
          ),
        ]),
      );

      if (picker) children.push(picker);

      children.push(
        E("div", { class: "aurora-store-share-cols" }, [
          E("div", { class: "aurora-store-share-prev" }, [
            E("div", { class: "aurora-store-prev" }, [
              buildDuo(
                {
                  light: {
                    bg: uci.get("aurora", "theme", "light_bg"),
                    surface: uci.get("aurora", "theme", "light_surface"),
                    text: uci.get("aurora", "theme", "light_text"),
                    brand: uci.get("aurora", "theme", "light_brand"),
                  },
                  dark: {
                    bg: uci.get("aurora", "theme", "dark_bg"),
                    surface: uci.get("aurora", "theme", "dark_surface"),
                    text: uci.get("aurora", "theme", "dark_text"),
                    brand: uci.get("aurora", "theme", "dark_brand"),
                  },
                },
                { nav: currentNav },
              ),
            ]),
            E(
              "p",
              { style: "font-size:0.75em;color:var(--text-muted);text-align:center;margin:6px 0 0;" },
              _("How it looks in the store"),
            ),
          ]),
          E("div", {}, [
            field(_("Name"), nameInput),
            field(_("Description"), descInput),
            buildIdentityField(field),
            progressEl,
            errEl,
          ]),
        ]),
      );

      children.push(
        E("h4", { style: "margin:1.2em 0 0.4em;" }, _("What gets shared")),
        manifestTable,
        E(
          "p",
          { style: "color:var(--text-muted);font-size:0.8em;margin-top:0.8em;" },
          _("Anyone who applies this gets all of it. You can update or remove it later."),
        ),
      );

      // 只在真的要发字体文件时才出现。字体和图标不是一回事:一个自己画的
      // logo 是自己的,而一份字体绝大多数情况下是别人的作品,多数商业授权
      // 明确不允许再分发。这句话必须在按下发布之前就在眼前,不能藏进条款。
      if (sharedFonts.length)
        children.push(
          E(
            "p",
            { class: "aurora-store-license-note" },
            _("This share includes your uploaded font file. Please make sure you have the right to redistribute it — most commercial font licences do not allow it. Configurations reported for infringement are taken down."),
          ),
        );

      children.push(
        E("div", { class: "right", style: "margin-top:1em;" }, [submitBtn]),
      );

      return E("div", { class: "aurora-store-share" }, children);
    };

    // ------------------------------------------------------------------
    // Header: search + tabs + share

    // count 是惰性的:builtinItems 在渲染前就定好了,myShares 要等 hub_my_shares
    // 回来。两个都读的是渲染那一刻的值,而不是定义这张表时的值。
    const TABS = [
      { key: "all", label: _("All") },
      { key: "builtin", label: _("Built-in"), count: () => builtinItems.length },
      { key: "hot", label: _("Hot") },
      { key: "new", label: _("New") },
      // 「我的分享」变成「我的」:这一页现在还收着「我的配置」那张卡,而它
      // 恰恰是唯一一份从没发布出去的东西。
      {
        key: "mine",
        label: _("Mine"),
        count: () => myShares.length + (buildMineModel() ? 1 : 0),
      },
    ];

    const renderTabLabel = (tab) => {
      const btn = tabButtons[tab.key];
      if (!btn) return;
      while (btn.firstChild) btn.removeChild(btn.firstChild);
      btn.appendChild(document.createTextNode(tab.label));
      const n = tab.count ? tab.count() : 0;
      if (n) btn.appendChild(E("span", { class: "n" }, [document.createTextNode(String(n))]));
    };

    const tabButtons = {};
    const tabsEl = E(
      "div",
      { class: "aurora-store-filters" },
      TABS.map((tab) => {
        const btn = E("button", { type: "button", click: () => selectTab(tab.key) });
        tabButtons[tab.key] = btn;
        return btn;
      }),
    );
    TABS.forEach(renderTabLabel);

    const searchInput = E("input", {
      type: "text",
      class: "cbi-input-text",
      placeholder: _("Search themes or authors…"),
    });
    searchInput.addEventListener("input", () => {
      state.query = searchInput.value.trim().toLowerCase();
      renderContent();
    });

    // Tabs and search share one row. They were stacked, and because nothing
    // sat to the left of the search box its row was a band of empty pixels
    // running the full width of the page -- the spacer was the only thing in
    // it. Now the spacer earns its keep: it is what holds the search box
    // against the right edge with the tab strip on the left.
    //
    // No heading here: the tab strip directly above already reads "Theme
    // Marketplace", and this printed the same words again a hand's width
    // below it. The publish button that used to sit next to the search box is
    // gone with the other two: this page no longer starts a publish at all.
    const headEl = E("div", { class: "aurora-store-head" }, [
      tabsEl,
      E("span", { class: "sp" }),
      searchInput,
    ]);

    // ------------------------------------------------------------------
    // Content sections

    const matchesQuery = (name, author) => {
      if (!state.query) return true;
      return (
        (name || "").toLowerCase().includes(state.query) ||
        (author || "").toLowerCase().includes(state.query)
      );
    };

    const buildBuiltinGrid = () => {
      const items = builtinItems.filter((preset) =>
        matchesQuery(preset.label, "Aurora"),
      );
      if (!items.length) return null;
      return E(
        "div",
        { class: "aurora-store-grid" },
        items.map((preset) => buildBuiltinCard(preset)),
      );
    };

    const buildOnlineGrid = (sort) => {
      const grid = E("div", { class: "aurora-store-grid", id: "hub-cards" });
      const items = state.online[sort];

      if (state.onlineFailed && !items) {
        grid.appendChild(
          E(
            "div",
            {
              style:
                "grid-column:1/-1;text-align:center;color:var(--text-muted);padding:2em 1em;",
            },
            [
              E("p", {}, _("Unable to reach the theme store right now.")),
              E(
                "button",
                {
                  type: "button",
                  class: "cbi-button cbi-button-apply",
                  click: () => fetchSort(sort),
                },
                _("Retry"),
              ),
            ],
          ),
        );
        return grid;
      }

      if (!items) {
        grid.appendChild(
          E(
            "p",
            {
              class: "spinning",
              style: "grid-column:1/-1;padding:1.5em 0;",
            },
            _("Loading…"),
          ),
        );
        fetchSort(sort);
        return grid;
      }

      const visible = items
        .filter((item) => !isBuiltinSeed(item))
        .filter((item) => matchesQuery(item.name, item.author));

      if (!visible.length) {
        grid.appendChild(
          E(
            "div",
            {
              style:
                "grid-column:1/-1;text-align:center;color:var(--text-muted);padding:2em 1em;",
            },
            state.query
              ? _("No themes match your search.")
              : _("No configs here yet — go share the first one."),
          ),
        );
        return grid;
      }

      visible.forEach((item) => grid.appendChild(buildOnlineCard(item)));
      return grid;
    };

    const buildStaleNotice = () =>
      state.showingStale
        ? E(
            "em",
            {
              style:
                "display:block;color:var(--text-muted);font-size:0.85em;margin-top:0.5em;",
            },
            _("Showing a saved copy — reconnecting…"),
          )
        : null;

    const renderContent = () => {
      while (contentEl.firstChild) contentEl.removeChild(contentEl.firstChild);
      const push = (node) => node && contentEl.appendChild(node);

      // 排在最前面:正在用的那张卡应该第一眼看见。既没改过、又没有可回去的
      // 配置时整段不出现 —— 那时用户还没有属于自己的东西。
      //
      // 「全部」页上它是一张卡:那一页是拿来逛的,内置和社区也是网格,它跟着
      // 一样才读得顺。「我的」页在下面单独处理 —— 那里它是主角,画成横幅。
      if (state.tab === "all") {
        const mineGrid = buildMineGrid();
        if (mineGrid) {
          push(buildSectionTitle(_("Mine"), _("On this router only")));
          push(mineGrid);
        }
      }

      if (state.tab === "all" || state.tab === "builtin") {
        const builtinGrid = buildBuiltinGrid();
        if (builtinGrid) {
          push(buildSectionTitle(_("Built-in"), _("Ships with the theme, works offline")));
          push(builtinGrid);
        }
      }

      if (state.tab === "all") {
        push(buildSectionTitle(_("Community"), _("Shared by other people")));
        push(buildStaleNotice());
        push(buildOnlineGrid("hot"));
      } else if (state.tab === "hot" || state.tab === "new") {
        push(buildStaleNotice());
        push(buildOnlineGrid(state.tab));
      } else if (state.tab === "mine") {
        // 发布态独占这一页。原先是顺着往下堆的:塞一张面板,然后照样再画一次
        // 区块标题和空态引导卡 —— 于是面板已经开着的时候,下面还在劝你"把这
        // 台路由器的整套外观发布到商店"。目标选择器已经把"你有哪些作品"说清
        // 楚了,底下再列一遍就是第二遍。
        if (shareOpen) {
          push(buildSharePanel());
          return;
        }
        // 一屏两个标题,不是三个。身份曾经占着和作品同一级的一个 section ——
        // 它是设施,不是目的,现在并进「我的分享」:这台路由器以谁的名义发布,
        // 说的本来就是下面那张表里的东西归谁。
        const banner = buildMineBanner();
        if (banner) {
          push(buildSectionTitle(_("Mine"), _("On this router only")));
          push(banner);
        }
        push(buildSectionTitle(_("My Shares"), ""));
        push(buildIdentityCard());
        push(mySharesEl);
      }
    };

    const selectTab = (key) => {
      state.tab = key;
      TABS.forEach((tab) =>
        tabButtons[tab.key].classList.toggle("active", tab.key === key),
      );
      renderContent();
    };

    // ------------------------------------------------------------------
    // Online data lifecycle: instant paint from cache, reconcile with the
    // network, degrade to the built-in group plus a retry notice on failure.

    const applyResult = (res, sort) => {
      if (res && res.result === 0 && res.data) {
        if (sort === "hot") hubApi.listCache.set(res.data);
        state.online[sort] = Array.isArray(res.data.items) ? res.data.items : [];
        state.onlineFailed = false;
        state.showingStale = false;
        renderContent();
        return;
      }

      const stale = sort === "hot" ? hubApi.listCache.getStale() : null;
      if (stale && Array.isArray(stale.items) && stale.items.length) {
        state.online.hot = stale.items;
        state.showingStale = true;
      } else {
        state.onlineFailed = true;
      }
      renderContent();
    };

    const fetchSort = (sort) =>
      L.resolveDefault(hubApi.callHubList(sort, 1), null).then((res) =>
        applyResult(res, sort),
      );

    // ------------------------------------------------------------------
    // Boot: cached hot list first (even stale), then reconcile with the
    // fetch load() already ran.

    const cached = hubApi.listCache.getStale();
    if (cached && Array.isArray(cached.items) && cached.items.length)
      state.online.hot = cached.items;

    // 缓存或 null。null 走空态,不是错误态 —— 一台刚装好的路由器本来就没有
    // 已发布的作品,和"拿不到数据"是两回事。
    applyMe(hubApi.meCache.getStale());
    // 从工作台带着发布意图过来,直接落在"我的分享"上,不必再点一次标签。
    selectTab(shareIntent ? "mine" : "all"); // 末行已 renderContent(),首帧在此成型

    [
      styleEl,
      headEl,
      contentEl,
      drawerMask,
      drawerEl,
    ].forEach((child) => rootEl.appendChild(child));

    // 网络在 DOM 挂载之后才发起。此刻画面已经成型:内置预设来自随包的
    // presets.json,在线列表与创作者档案来自上面两处缓存。两个请求回来后
    // 各自 reconcile,失败则保留当前这帧。
    fetchSort("hot");
    refreshMyShares();

    return rootEl;
  },
});
